// Returns the row if successful; pgx.ErrNoRows if already redeemed.
func (q *Queries) RedeemCouponCode(ctx context.Context, arg RedeemCouponCodeParams) (CouponCode, error) {
	row := q.db.QueryRow(ctx, redeemCouponCode, arg.ID, arg.RedeemedBy, arg.RedeemedByOrderID)
	var i CouponCode
	err := row.Scan(
		&i.ID,
		&i.DiscountID,
		&i.Code,
		&i.CustomerID,
		&i.RedeemedAt,
		&i.RedeemedBy,
		&i.CreatedAt,
		&i.RedeemedByOrderID,
	)
	return i, err
}

const releaseCouponCodeByOrderID = `-- name: ReleaseCouponCodeByOrderID :exec
UPDATE coupon_codes
SET redeemed_at = NULL,
    redeemed_by = NULL,
    redeemed_by_order_id = NULL
WHERE redeemed_by_order_id = $1
`

// Reverses a coupon redemption tied to a specific order. Used when an order
// is cancelled (admin or abandoned-checkout cleanup) so the code can be used
// again. No-op if the coupon was never redeemed for that order.
func (q *Queries) ReleaseCouponCodeByOrderID(ctx context.Context, redeemedByOrderID *uuid.UUID) error {
	_, err := q.db.Exec(ctx, releaseCouponCodeByOrderID, redeemedByOrderID)
	return err
}

const updateDiscount = `-- name: UpdateDiscount :one
UPDATE discounts
SET name = $2, description = $3, type = $4, value = $5, minimum_order_cents = $6,
    starts_at = $7, expires_at = $8, active = $9, eligibility = $10, applies_to = $11, updated_at = now()
WHERE id = $1
RETURNING id, name, description, type, value, minimum_order_cents, starts_at, expires_at, active, created_at, updated_at, usage_limit, eligibility, applies_to, is_referral
`

type UpdateDiscountParams struct {
	ID                uuid.UUID          `json:"id"`
	Name              string             `json:"name"`
	Description       *string            `json:"description"`
	Type              string             `json:"type"`
	Value             int32              `json:"value"`
	MinimumOrderCents *int32             `json:"minimum_order_cents"`
	StartsAt          pgtype.Timestamptz `json:"starts_at"`
	ExpiresAt         pgtype.Timestamptz `json:"expires_at"`
	Active            bool               `json:"active"`
	Eligibility       string             `json:"eligibility"`
	AppliesTo         string             `json:"applies_to"`
}

func (q *Queries) UpdateDiscount(ctx context.Context, arg UpdateDiscountParams) (Discount, error) {
	row := q.db.QueryRow(ctx, updateDiscount,
		arg.ID,
		arg.Name,
		arg.Description,
		arg.Type,
		arg.Value,
		arg.MinimumOrderCents,
		arg.StartsAt,
		arg.ExpiresAt,
		arg.Active,
		arg.Eligibility,
		arg.AppliesTo,
	)
	var i Discount
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Description,
		&i.Type,
		&i.Value,
		&i.MinimumOrderCents,
		&i.StartsAt,
		&i.ExpiresAt,
		&i.Active,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.UsageLimit,
		&i.Eligibility,
		&i.AppliesTo,
		&i.IsReferral,
	)
	return i, err
}

const voidReferralRewardByOrderID = `-- name: VoidReferralRewardByOrderID :exec
UPDATE referral_rewards SET status = 'void'
WHERE order_id = $1 AND status = 'owed'
`

// A cancelled order takes back the bag it earned, unless it already went out.
func (q *Queries) VoidReferralRewardByOrderID(ctx context.Context, orderID uuid.UUID) error {
	_, err := q.db.Exec(ctx, voidReferralRewardByOrderID, orderID)
	return err
}
